 "content": "from collections import deque


def transform(grid):
    """Bridge collinear foreground components; render the added bridge as 2."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Label original 4-connected components; do not let newly drawn bridges
    # influence which pairs are selected.
    labels = [[-1] * w for _ in range(h)]
    component = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or labels[r][c] != -1:
                continue
            labels[r][c] = component
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != background and labels[ny][nx] == -1:
                        labels[ny][nx] = component
                        q.append((ny, nx))
            component += 1

    out = [row[:] for row in grid]
    # For consecutive marks on a row/column, draw a bridge only when they
    # belong to different original components.
    for r in range(h):
        marks = [c for c in range(w) if labels[r][c] >= 0]
        for a, b in zip(marks, marks[1:]):
            if labels[r][a] != labels[r][b]:
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if labels[r][c] >= 0]
        for a, b in zip(marks, marks[1:]):
            if labels[a][c] != labels[b][c]:
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out


if __name__ == "__main__":
    print("transform(grid) is ready")
  ",
